CREATE TABLE public.official_brokers_registry (license_number text PRIMARY KEY, holder_name text NOT NULL, source_url text NOT NULL, source_updated_at timestamptz NOT NULL, checked_at timestamptz NOT NULL DEFAULT now());
GRANT ALL ON public.official_brokers_registry TO service_role;
ALTER TABLE public.official_brokers_registry ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.broker_role_suspensions (user_id uuid NOT NULL, role public.app_role NOT NULL, suspended_at timestamptz NOT NULL DEFAULT now(), reason text NOT NULL DEFAULT 'official_registry_verification_required', PRIMARY KEY(user_id,role));
GRANT SELECT ON public.broker_role_suspensions TO authenticated;
GRANT ALL ON public.broker_role_suspensions TO service_role;
ALTER TABLE public.broker_role_suspensions ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_license_suspensions ON public.broker_role_suspensions FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE OR REPLACE FUNCTION public.official_license_exists(_number text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT COALESCE(_number ~ '^[1-9][0-9]{0,9}$',false) AND EXISTS(SELECT 1 FROM public.official_brokers_registry WHERE license_number=_number AND source_url='https://data.gov.il/dataset/d361f6a6-898c-4e4d-8a80-abc4e8643bf6' AND source_updated_at > now()-interval '7 days' AND source_updated_at <= now()+interval '1 minute' AND extract(year from source_updated_at)=extract(year from now())) $$;
CREATE OR REPLACE FUNCTION public.has_verified_broker_license(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.profiles p WHERE p.id=_uid AND public.official_license_exists(p.broker_license_number)) $$;
CREATE OR REPLACE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) AND (_role NOT IN ('agent','lead_agent','managing_broker','junior_agent') OR public.has_verified_broker_license(_user_id)) $$;
CREATE OR REPLACE FUNCTION public.enforce_official_broker_role() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.role IN ('agent','lead_agent','managing_broker','junior_agent') AND NOT public.has_verified_broker_license(NEW.user_id) THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_official_broker_role BEFORE INSERT OR UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.enforce_official_broker_role();
CREATE OR REPLACE FUNCTION public.enforce_official_profile_license() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.broker_license_number IS DISTINCT FROM OLD.broker_license_number OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.id AND role IN ('agent','lead_agent','managing_broker','junior_agent'))) THEN IF (NULLIF(NEW.broker_license_number,'') IS NOT NULL OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=NEW.id AND role IN ('agent','lead_agent','managing_broker','junior_agent'))) AND NOT public.official_license_exists(NEW.broker_license_number) THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; ELSIF TG_OP='INSERT' AND NULLIF(NEW.broker_license_number,'') IS NOT NULL AND NOT public.official_license_exists(NEW.broker_license_number) THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; RETURN NEW; END $$;
CREATE TRIGGER enforce_official_profile_license BEFORE INSERT OR UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.enforce_official_profile_license();
CREATE OR REPLACE FUNCTION public.affiliate_tier3_eligible(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.affiliate_profiles WHERE user_id=_user_id AND license_status='verified' AND public.official_license_exists(license_number)) $$;
CREATE OR REPLACE FUNCTION public.can_close_deal(_user_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_verified_broker_license(_user_id) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role IN ('managing_broker','lead_agent','agent')) $$;
CREATE OR REPLACE FUNCTION public.get_verified_user_roles() RETURNS SETOF public.app_role LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT role FROM public.user_roles WHERE user_id=auth.uid() AND (role NOT IN ('agent','lead_agent','managing_broker','junior_agent') OR public.has_verified_broker_license(user_id)) $$;
REVOKE ALL ON FUNCTION public.get_verified_user_roles() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.get_verified_user_roles() TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.complete_official_license_verification(_uid uuid,_number text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.official_license_exists(_number) THEN RAISE EXCEPTION 'invalid_official_license'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended(_uid::text,0)); UPDATE public.profiles SET broker_license_number=_number WHERE id=_uid; INSERT INTO public.user_roles(user_id,role) SELECT user_id,role FROM public.broker_role_suspensions WHERE user_id=_uid ON CONFLICT(user_id,role) DO NOTHING; DELETE FROM public.broker_role_suspensions WHERE user_id=_uid; END $$;
REVOKE ALL ON FUNCTION public.complete_official_license_verification(uuid,text) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.complete_official_license_verification(uuid,text) TO service_role;
CREATE OR REPLACE FUNCTION public.submit_affiliate_license(_license_number text,_holder_name text DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'auth_required'; END IF; IF NOT public.official_license_exists(_license_number) OR NOT EXISTS(SELECT 1 FROM public.broker_license_verifications WHERE user_id=uid AND license_number=_license_number AND verified_at>now()-interval '24 hours') THEN RAISE EXCEPTION 'מספר הרישיון אינו תקף או אינו מופיע בפנקס המתווכים המורשים'; END IF; INSERT INTO public.affiliate_profiles(user_id,license_number,license_holder_name,license_status,license_submitted_at) VALUES(uid,_license_number,(SELECT holder_name FROM public.official_brokers_registry WHERE license_number=_license_number),'pending',now()) ON CONFLICT(user_id) DO UPDATE SET license_number=excluded.license_number,license_holder_name=excluded.license_holder_name,license_status='pending',license_submitted_at=now(); RETURN jsonb_build_object('ok',true,'status','pending'); END $$;
CREATE OR REPLACE FUNCTION public.suspend_unverified_broker_roles() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE affected integer; BEGIN INSERT INTO public.broker_role_suspensions(user_id,role) SELECT user_id,role FROM public.user_roles WHERE role IN ('agent','lead_agent','managing_broker','junior_agent') AND NOT public.has_verified_broker_license(user_id) ON CONFLICT(user_id,role) DO NOTHING; DELETE FROM public.user_roles WHERE role IN ('agent','lead_agent','managing_broker','junior_agent') AND NOT public.has_verified_broker_license(user_id); GET DIAGNOSTICS affected=ROW_COUNT; RETURN affected; END $$;
REVOKE ALL ON FUNCTION public.suspend_unverified_broker_roles() FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.suspend_unverified_broker_roles() TO service_role;